*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#f5f8f6;--ink:#071c2a;--panel:rgba(9,28,40,.88);--muted:#a6bbc0;--gold:#ffcf74;--mint:#68e0b0}html,body{height:100%;margin:0;overflow:hidden;background:#08263a}body{user-select:none;-webkit-user-select:none;touch-action:none}.game-shell{position:relative;width:100vw;height:100dvh;min-height:540px;overflow:hidden;background:#0a5364}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(4,21,32,.48),transparent 22%,transparent 73%,rgba(4,19,29,.48)),linear-gradient(90deg,rgba(4,22,32,.18),transparent 23%,transparent 78%,rgba(4,22,32,.22))}.topbar{position:absolute;top:0;left:0;right:0;height:78px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09);background:linear-gradient(180deg,rgba(4,23,34,.76),rgba(4,23,34,.22));z-index:3}.brand{display:flex;align-items:center;gap:11px;color:#fff;text-decoration:none}.brand-mark{width:39px;height:39px;display:grid;place-items:center;border:1px solid rgba(255,210,122,.68);border-radius:12px;background:linear-gradient(145deg,#ee9c55,#bd5543);box-shadow:0 5px 18px #07233580;color:#ffe4a8;font-size:23px;transform:rotate(-5deg)}.brand-word{font-family:Outfit,sans-serif;font-weight:800;font-size:18px;letter-spacing:1.2px;line-height:17px}.brand-word>span{color:#ffd37c}.brand-word small{display:block;color:#a6c2c4;font:600 8px 'DM Sans',sans-serif;letter-spacing:2px;margin-top:5px}.server-pill{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;font-size:10px;font-weight:800;letter-spacing:1.4px;color:#dce8df}.server-pill i,.online-dot,.ping-dot{width:6px;height:6px;border-radius:50%;background:#76e3a8;box-shadow:0 0 9px #76e3a8}.server-pill b{color:#647c7e}.server-pill small{font-size:9px;color:#9eb8b7;letter-spacing:1px;padding:5px 8px;border:1px solid #ffffff24;border-radius:5px;background:#ffffff0b;margin-left:4px}.top-actions{display:flex;gap:9px;align-items:center}.icon-btn,.avatar-btn{height:36px;width:36px;border:1px solid #ffffff25;border-radius:10px;background:#071e2b9e;color:#d1e2df;font-size:17px;cursor:pointer}.icon-btn:hover,.avatar-btn:hover{background:#ffffff20}.avatar-btn{border-radius:50%;background:linear-gradient(140deg,#e7a762,#a84f44);border:2px solid #f7d29a;font-weight:800;color:#fff}.panel{position:absolute;z-index:2;background:linear-gradient(145deg,rgba(8,29,42,.94),rgba(12,39,49,.86));border:1px solid rgba(210,238,223,.15);border-radius:13px;box-shadow:0 12px 30px #04162150;backdrop-filter:blur(11px)}.player-card{top:100px;left:36px;width:280px;padding:14px 15px 13px}.player-line{display:flex;align-items:center;gap:10px;margin-bottom:14px}.portrait{width:40px;height:40px;border-radius:11px;display:grid;place-items:center;background:linear-gradient(145deg,#fac67b,#d7784d);border:1px solid #f9d79c;color:#633f2c;font-size:21px;box-shadow:inset 0 0 0 2px #ffffff38}.player-copy{flex:1}.player-copy strong{display:block;font:800 12px Outfit,sans-serif;letter-spacing:.8px}.player-copy span{display:block;margin-top:3px;font-size:8px;letter-spacing:1px;color:#91aaa9}.level-badge{font-size:8px;color:#a5bbb6;background:#ffffff0c;padding:6px 7px;border-radius:6px}.level-badge b{font:800 12px Outfit,sans-serif;color:#ffcf74;margin-left:3px}.stat-row{height:16px;display:flex;align-items:center;gap:7px;margin:6px 0}.stat-icon{width:13px;text-align:center;font-size:12px}.heart{color:#ff7373}.bolt{color:#70dff0}.meter{height:7px;flex:1;background:#ffffff15;border-radius:6px;overflow:hidden}.meter-fill{height:100%;border-radius:6px;transition:width .25s}.health-fill{background:linear-gradient(90deg,#ef6269,#ff9576);box-shadow:0 0 9px #fa766a75}.energy-fill{background:linear-gradient(90deg,#4db9cf,#75e4dd)}.stat-row>b{font-size:10px;min-width:61px;text-align:right}.stat-row>b small{font-size:9px;color:#81989a;font-weight:500}.xp-row{display:flex;align-items:center;gap:7px;margin-top:12px;color:#8da6a7;font-size:8px;font-weight:800;letter-spacing:.8px}.xp-meter{height:4px}.xp-fill{background:linear-gradient(90deg,#f3bb62,#ffe08b)}.xp-row>b{min-width:54px;font-size:8px;text-align:right;color:#e3cb91;font-weight:600;letter-spacing:0}.quest-card{top:280px;left:36px;width:280px;padding:13px 15px 12px;border-top:2px solid #f2c06c}.eyebrow,.tiny-label{font-size:8px;font-weight:800;letter-spacing:1.3px;color:#a6bab7}.quest-icon{color:#ffd57f;font-size:12px;margin-right:4px}.quest-dots{float:right;letter-spacing:2px;color:#7f9692;font-size:12px}.quest-title{font:700 16px Outfit,sans-serif;margin:11px 0 3px}.quest-sub{font-size:10px;color:#9cb2b1}.quest-progress{display:flex;align-items:center;gap:9px;margin:12px 0 10px}.quest-bar{height:5px;border-radius:5px;background:#ffffff18;flex:1;overflow:hidden}.quest-bar i{display:block;height:100%;width:0;background:#f5c46e;border-radius:5px;transition:width .3s}.quest-progress span{font-size:9px;color:#e2c98e;font-weight:700;min-width:26px}.quest-reward{font-size:10px;font-weight:700;color:#e6d7a8}.quest-reward>span:first-child{color:#76ddba}.quest-reward small{font-size:8px;color:#a2b3aa}.reward-sep{color:#70827e;margin:0 7px}.star{color:#ffd375}.crew-card{top:100px;right:36px;width:245px;padding:13px 14px 11px}.crew-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:11px}.crew-head .tiny-label{display:block;font-size:7px;color:#8ca9a6;margin-bottom:4px}.crew-head strong{font:600 12px Outfit,sans-serif}.crew-head em{font-style:normal;color:#ffd17a;font-size:10px;margin-left:4px}.dots-btn{border:0;background:none;color:#91aaa6;letter-spacing:2px;cursor:pointer}.crew-member{display:flex;align-items:center;gap:8px;margin:8px 0}.crew-avatar{height:29px;width:29px;border-radius:9px;display:grid;place-items:center;color:#fff;font-size:13px;border:1px solid #ffffff24}.ca-one{background:linear-gradient(140deg,#7cc9bd,#397886)}.ca-two{background:linear-gradient(140deg,#ca795c,#7c3d43)}.ca-three{background:linear-gradient(140deg,#8c92bc,#494d75)}.crew-member>span{display:flex;flex-direction:column;flex:1}.crew-member b{font-size:10px}.crew-member span small{font-size:8px;color:#8fa6a4;margin-top:2px}.crew-member .online-dot{height:5px;width:5px}.crew-lvl{font-size:8px;color:#90aaa6}.crew-foot{margin:11px -14px -11px;padding:10px 14px;border-top:1px solid #ffffff12;font-size:8px;color:#8fa6a2;display:flex;align-items:center;gap:7px}.ping-dot{height:5px;width:5px}.location-chip{position:absolute;left:36px;bottom:104px;z-index:2;display:flex;align-items:center;gap:9px;padding:9px 13px;background:#071e2ca8;border:1px solid #ffffff1b;border-radius:9px;backdrop-filter:blur(8px)}.location-chip>span{font-size:20px;color:#f2c46f}.location-chip b,.location-chip small{display:block}.location-chip b{font:600 11px Outfit,sans-serif}.location-chip small{font-size:8px;color:#a1b7b2;margin-top:3px}.location-chip small i{font-style:normal;color:#f4c46c}.objective-hint{position:absolute;bottom:115px;left:50%;transform:translateX(-50%);z-index:2;display:flex;align-items:center;gap:7px;color:#b8c8c0;font-size:9px;text-shadow:0 2px 6px #001721}.objective-hint i{font-style:normal;color:#668078;margin:0 4px}.keycap{font-size:8px;letter-spacing:.6px;padding:4px 6px;border-radius:4px;background:#132d36c9;border:1px solid #ffffff35;color:#e0e9dc}.hotbar-wrap{position:absolute;z-index:3;bottom:22px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px}.hotbar{display:flex;gap:7px;padding:7px;background:#071b27dc;border:1px solid #ffffff24;border-radius:13px;box-shadow:0 8px 25px #02131c70;backdrop-filter:blur(12px)}.skill{width:64px;height:62px;position:relative;border:1px solid #ffffff18;border-radius:9px;background:linear-gradient(145deg,#163442,#0c2633);color:#eaf1e9;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;overflow:hidden;transition:.15s}.skill:hover{border-color:#e8c377a8;transform:translateY(-3px);background:#1b3c48}.skill-key{position:absolute;left:5px;top:4px;font-size:7px;letter-spacing:.4px;color:#a8b7b3;background:#ffffff13;padding:2px 4px;border-radius:3px}.skill-symbol{font-size:21px;color:#f1d29a;line-height:24px;text-shadow:0 2px 8px #f4ba66a0}.gum-symbol{color:#a7e8d0}.skill b{font-size:8px;font-weight:600;color:#c0cfca}.basic-skill{border-color:#e6c77e60}.dash-skill .skill-symbol{color:#9edff0}.cooldown{position:absolute;inset:0;background:#04131dc0;transform:translateY(100%);transition:transform .15s}.skill.cooling .cooldown{transform:translateY(0)}.skill.cooling{filter:saturate(.6);pointer-events:none}.fruit-chip,.cash-chip{height:57px;display:flex;align-items:center;gap:8px;background:#071b27d9;border:1px solid #ffffff21;border-radius:11px;padding:7px 10px;box-shadow:0 6px 20px #02131c55;backdrop-filter:blur(12px);position:relative;overflow:hidden}.fruit-icon{height:36px;width:36px;border-radius:9px;background:linear-gradient(145deg,#4fac92,#206d66);display:grid;place-items:center;font-size:22px;border:1px solid #98e3be80;box-shadow:0 0 15px #59c79555}.fruit-chip>span{display:flex;flex-direction:column;gap:4px;white-space:nowrap}.fruit-chip small{font-size:7px;letter-spacing:1px;color:#86a8a2;font-weight:700}.fruit-chip b{font:600 11px Outfit,sans-serif}.fruit-glow{position:absolute;width:25px;height:50px;background:#74e3ad20;filter:blur(15px);right:6px}.cash-chip{height:42px;padding:5px 7px 5px 11px;color:#f6d280}.cash-chip>span{font:bold 20px Outfit,sans-serif}.cash-chip b{font-size:10px;color:#e8eadd}.cash-chip button{height:28px;width:28px;border:1px solid #ffffff20;background:#ffffff0b;border-radius:7px;color:#f5d17c;font-size:18px;margin-left:3px;cursor:pointer}.world-toast{position:absolute;left:50%;top:23%;z-index:4;transform:translate(-50%,-10px);padding:11px 16px;border:1px solid #ffe09972;border-radius:10px;background:#102e36ed;box-shadow:0 9px 24px #051b25a0;text-align:center;opacity:0;pointer-events:none;transition:all .35s}.world-toast.show{opacity:1;transform:translate(-50%,0)}.world-toast span{color:#ffcf74;margin-right:6px}.world-toast b{font:700 13px Outfit}.world-toast small{display:block;font-size:9px;color:#b7c9b9;margin-top:3px}.mobile-controls{display:none}.map-overlay{display:none;position:absolute;inset:0;z-index:10;background:#03131ccc;backdrop-filter:blur(8px);align-items:center;justify-content:center}.map-overlay.open{display:flex}.map-window{position:relative;width:min(470px,90vw);padding:26px;background:#0b2734;border:1px solid #ffffff25;border-radius:16px;box-shadow:0 25px 80px #0008}.map-window>button{position:absolute;right:16px;top:12px;color:#fff;background:none;border:0;font-size:25px;cursor:pointer}.map-window h2{font:700 25px Outfit;margin:7px 0 17px}.mini-map{height:230px;border-radius:12px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 50% 50%,#368d82 0 24%,#d1b576 24.5% 31%,transparent 31.5%),linear-gradient(135deg,#0d6678,#16546a 55%,#0a4158);border:1px solid #ffffff28}.mini-map:before,.mini-map:after{content:'';position:absolute;background:#74a889;border:8px solid #d5bd85;border-radius:50%;width:58px;height:36px;left:11%;top:24%;transform:rotate(-27deg)}.mini-map:after{left:73%;top:57%;width:75px;height:44px;transform:rotate(22deg)}.map-island{position:absolute;left:49%;top:44%;font-size:27px;color:#ffe283;z-index:2}.map-player{position:absolute;left:50%;top:46%;font-style:normal;color:#fff;font-size:12px;z-index:3;text-shadow:0 0 7px #fff}.mini-map>b{position:absolute;left:50%;top:64%;transform:translateX(-50%);font-size:7px;letter-spacing:1px;color:white}.mini-map>small{position:absolute;left:50%;top:10%;transform:translateX(-50%);font-size:8px;letter-spacing:2px;color:#d5f1dc}.map-window p{margin:14px 0 0;color:#a9bfba;font-size:11px}.level-toast{position:absolute;top:36%;left:50%;z-index:5;transform:translate(-50%,-10px) scale(.9);display:flex;flex-direction:column;align-items:center;padding:18px 30px;border:1px solid #ffdc8590;background:linear-gradient(145deg,#385e55f2,#132e3bf2);border-radius:14px;box-shadow:0 0 35px #fed07c38;opacity:0;pointer-events:none;transition:.3s}.level-toast.show{opacity:1;transform:translate(-50%,0) scale(1)}.level-toast span{font-size:22px;color:#ffda8b}.level-toast b{font:800 19px Outfit;letter-spacing:2px;color:#ffe4a2}.level-toast small{margin-top:5px;font-size:10px;color:#d2dfd3}.level-toast i{font-style:normal;color:#ffe5a0;font-weight:800}
