@media(max-width:600px){.game-shell{min-height:480px}.topbar{height:56px;padding:0 13px}.brand-mark{width:32px;height:32px;font-size:19px;border-radius:9px}.brand-word{font-size:15px;line-height:14px}.brand-word small{font-size:6px;letter-spacing:1.5px}.server-pill{top:61px;left:50%;font-size:8px;padding:5px 9px;background:#082530b8;border-radius:20px;white-space:nowrap}.server-pill small{padding:3px 6px}.top-actions{gap:5px}.icon-btn,.avatar-btn{width:31px;height:31px;font-size:15px}.player-card{top:92px;left:10px;width:204px;padding:10px}.player-line{margin-bottom:8px;gap:7px}.portrait{width:32px;height:32px}.player-copy strong{font-size:10px}.player-copy span{font-size:7px}.level-badge{padding:5px}.stat-row{gap:5px;margin:4px 0;height:14px}.stat-row>b{font-size:9px;min-width:55px}.quest-card{top:auto;left:10px;bottom:160px;width:204px;padding:10px 11px}.quest-title{font-size:13px;margin:7px 0 2px}.quest-sub{font-size:8px}.quest-progress{margin:8px 0}.quest-reward{font-size:8px}.crew-card{top:auto;right:10px;bottom:159px;width:154px;padding:9px}.crew-head{margin-bottom:5px}.crew-head strong{font-size:10px}.crew-head .tiny-label{font-size:6px}.crew-member{gap:5px;margin:5px 0}.crew-avatar{width:23px;height:23px}.crew-member b{font-size:8px}.crew-member span small{font-size:7px}.crew-lvl{display:none}.crew-foot{margin:7px -9px -9px;padding:7px 9px;font-size:7px}.objective-hint{display:none}.location-chip{left:10px;bottom:119px;padding:6px 9px}.location-chip>span{font-size:17px}.location-chip b{font-size:9px}.location-chip small{font-size:7px}.hotbar-wrap{bottom:10px;gap:0}.hotbar{padding:5px;gap:4px;border-radius:11px}.skill{width:53px;height:54px}.skill-symbol{font-size:17px;line-height:20px}.skill b{font-size:7px}.skill-key{left:4px;top:3px;font-size:6px;padding:2px 3px}.mobile-controls{display:block}.joystick{position:absolute;bottom:24px;left:18px;z-index:4;width:95px;height:95px;border-radius:50%;background:#071d2b88;border:1px solid #ffffff42;touch-action:none}.joy-knob{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:38px;height:38px;border-radius:50%;background:linear-gradient(145deg,#e7c37b,#c39051);border:2px solid #f6df9e;box-shadow:0 3px 12px #0006}.mobile-attack{position:absolute;z-index:4;right:19px;bottom:32px;height:58px;width:58px;border-radius:50%;border:2px solid #f1d18e;background:linear-gradient(145deg,#ba6849,#793f40);color:#ffe7b0;font-size:24px;box-shadow:0 5px 18px #081b25aa}.map-btn{display:none}.world-toast{top:28%}.level-toast{top:35%}}
